-- 1. Casillas que no existen todavía
INSERT INTO sirve.casilla (id_seccion, clave, tipo, activa)
SELECT s.id,
       '2024-NL-' || m.clave || '-' || v.seccion || '-' || v.tipo,
       v.tipo,
       true
  FROM carga v
  JOIN sirve.entidad e ON e.clave = '19'
  JOIN sirve.proceso_electoral p ON p.id_entidad = e.id AND p.anio = 2024
  JOIN sirve.seccion s ON s.id_proceso = p.id AND s.clave = v.seccion
  JOIN sirve.municipio m ON m.id = s.id_municipio
 WHERE NOT EXISTS (SELECT 1 FROM sirve.casilla k
                    WHERE k.clave = '2024-NL-' || m.clave || '-' || v.seccion || '-' || v.tipo);

-- 2. Pertenencia a la elección federal
INSERT INTO sirve.casilla_eleccion (id_casilla, id_eleccion)
SELECT k.id, el.id
  FROM carga v
  JOIN sirve.entidad e ON e.clave = '19'
  JOIN sirve.proceso_electoral p ON p.id_entidad = e.id AND p.anio = 2024
  JOIN sirve.seccion s ON s.id_proceso = p.id AND s.clave = v.seccion
  JOIN sirve.municipio m ON m.id = s.id_municipio
  JOIN sirve.casilla k ON k.clave = '2024-NL-' || m.clave || '-' || v.seccion || '-' || v.tipo
  JOIN sirve.eleccion el ON el.id_proceso = p.id AND el.clave = 'DIPFED'
 WHERE NOT EXISTS (SELECT 1 FROM sirve.casilla_eleccion ce
                    WHERE ce.id_casilla = k.id AND ce.id_eleccion = el.id);

-- 3. Capturas
INSERT INTO sirve.captura (id_cliente, id_casilla, id_eleccion,
                           total_acta, no_registrados, nulos, suma_opciones)
SELECT gen_random_uuid(), k.id, el.id, v.total, v.no_registrados, v.nulos,
       (SELECT coalesce(sum(x::integer), 0)
          FROM unnest(string_to_array(v.votos, ',')) AS x)
  FROM carga v
  JOIN sirve.entidad e ON e.clave = '19'
  JOIN sirve.proceso_electoral p ON p.id_entidad = e.id AND p.anio = 2024
  JOIN sirve.seccion s ON s.id_proceso = p.id AND s.clave = v.seccion
  JOIN sirve.municipio m ON m.id = s.id_municipio
  JOIN sirve.casilla k ON k.clave = '2024-NL-' || m.clave || '-' || v.seccion || '-' || v.tipo
  JOIN sirve.eleccion el ON el.id_proceso = p.id AND el.clave = 'DIPFED'
ON CONFLICT (id_casilla, id_eleccion) DO NOTHING;

-- 4. Votos por opción
INSERT INTO sirve.captura_voto (id_captura, id_opcion, votos)
SELECT c.id, o.id, t.votos::integer
  FROM carga v
  JOIN sirve.entidad e ON e.clave = '19'
  JOIN sirve.proceso_electoral p ON p.id_entidad = e.id AND p.anio = 2024
  JOIN sirve.seccion s ON s.id_proceso = p.id AND s.clave = v.seccion
  JOIN sirve.municipio m ON m.id = s.id_municipio
  JOIN sirve.casilla k ON k.clave = '2024-NL-' || m.clave || '-' || v.seccion || '-' || v.tipo
  JOIN sirve.eleccion el ON el.id_proceso = p.id AND el.clave = 'DIPFED'
  JOIN sirve.captura c ON c.id_casilla = k.id AND c.id_eleccion = el.id
  CROSS JOIN LATERAL unnest(string_to_array(v.votos, ',')) WITH ORDINALITY AS t(votos, orden)
  JOIN sirve.opcion_boleta o ON o.id_eleccion = el.id AND o.orden = t.orden
 WHERE t.votos::integer > 0
ON CONFLICT (id_captura, id_opcion) DO NOTHING;

COMMIT;

-- Comprobación
SELECT count(*) AS capturas, sum(total_acta) AS votos,
       count(*) FILTER (WHERE NOT aritmetica_ok) AS inconsistentes
  FROM sirve.captura c
  JOIN sirve.eleccion el ON el.id = c.id_eleccion
 WHERE el.clave = 'DIPFED';
